const fs = require('fs');
const dir = '/data/talenza';
const filePath = dir + '/candidates.json';

let text = $input.first().json.candidates[0].content.parts[0].text;
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let c;
try { c = JSON.parse(text); } catch(e) { throw new Error('JSON parse failed: ' + e.message + '\nRaw: ' + text.substring(0, 500)); }

if (!c.candidate_id || !c.identity) throw new Error('Missing candidate_id or identity');

const comps = ['crisis_management','operational_depth','change_adaptability','stakeholder_trust','external_network'];
for (const k of comps) {
  if (!c.competency_signals?.[k]) {
    c.competency_signals = c.competency_signals || {};
    c.competency_signals[k] = { score_raw: 0, evidence: [], gaps: ['No data'] };
  }
}
c.source_type = 'internal';
c.created_at = new Date().toISOString();

if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
let all = [];
if (fs.existsSync(filePath)) { try { all = JSON.parse(fs.readFileSync(filePath, 'utf8')); } catch(e) {} }
const idx = all.findIndex(x => x.candidate_id === c.candidate_id);
if (idx >= 0) all[idx] = c; else all.push(c);
fs.writeFileSync(filePath, JSON.stringify(all, null, 2));

return [{ json: c }];

