const fs = require('fs');
const dir = '/data/talenza';
const filePath = dir + '/scenarios.json';
const track = $('Webhook - Scenario').first().json.body.track;

let text = $input.first().json.candidates[0].content.parts[0].text;
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let s;
try { s = JSON.parse(text); } catch(e) { throw new Error('Parse failed: ' + e.message); }

const fw = s.derived?.weight_calculation?.final_weights;
if (fw) {
  const dims = ['crisis_mgmt','ops_depth','change_adapt','stakeholder','external_net'];
  const sum = dims.reduce((a,k) => a + (fw[k]?.value||0), 0);
  if (sum > 0 && Math.abs(sum-1) > 0.05) {
    for (const k of dims) { if (fw[k]) fw[k].value = Math.round(fw[k].value/sum*1000)/1000; }
  }
}

const comp = s.derived?.completeness;
const needsQA = !(comp?.is_complete) || (comp?.null_mandatory_fields?.length > 0);

const questions = [
  ...(comp?.null_mandatory_fields||[]).map(f => ({ type:'missing', field:f.field_path, question:f.qa_question })),
  ...(comp?.low_confidence_weights_requiring_validation||[]).map(w => ({ type:'weight', dimension:w.dimension, question:w.validation_question }))
];

if (!needsQA) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  let all = [];
  if (fs.existsSync(filePath)) { try { all = JSON.parse(fs.readFileSync(filePath,'utf8')); } catch(e) {} }
  s.meta = s.meta || { scenario_id: 'scenario_'+Date.now() };
  const idx = all.findIndex(x => x.meta?.scenario_id === s.meta.scenario_id);
  if (idx >= 0) all[idx] = s; else all.push(s);
  fs.writeFileSync(filePath, JSON.stringify(all, null, 2));
}

return [{ json: { needs_qa: needsQA, track, scenario: s, questions } }];

